"""Cyclic group   [⟨g⟩]

Category : Math > Abstract algebra
Formula  : A group generated by a single element g: {…, g⁻¹, e, g, g², …}

Status   : ready to use - call compute(g, op, identity)
"""

NAME = 'Cyclic group'
SYMBOL = '⟨g⟩'
CATEGORY = 'Math'
SUBCATEGORY = 'Abstract algebra'
FORMULA = 'A group generated by a single element g: {…, g⁻¹, e, g, g², …}'
import math
from operators_one_operator_per_file import _helpers as H


def compute(g, op, identity):
    """The elements generated by g:  g, g², g³, … until the identity is reached"""
    out, x = [g], g
    for _ in range(10000):
        if x == identity:
            return out
        x = op(x, g)
        out.append(x)
    raise ValueError("g never returns to the identity")
